import json, re, random, time, chess, os, sys

RULES = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 're.json')))


def run(fen):
    for p, r in RULES:
        fen = re.sub(p, r, fen)
    return fen.split("\n")


def expected(fen):
    b = chess.Board(fen)
    out = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        c = b.copy(); c.push(m)
        out.add(" ".join(c.fen().split(" ")[:-2]))
    return out


def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    ok = len(ours) == len(exp) and len(set(ours)) == len(ours) and all(
        x in exp or x.rpartition(" ")[0] + " -" in exp for x in ours)
    if not ok:
        print("FAIL", fen)
        print(" extra:", [x for x in ours if not (x in exp or x.rpartition(" ")[0] + " -" in exp)])
        print(" missing:", [x for x in exp if x not in ours and not any(y.rpartition(" ")[0] + " -" == x for y in ours)])
    return ok


s = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"
print(run(s))
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0; fails = 0; t0 = time.time()
for g in range(int(sys.argv[2]) if len(sys.argv) > 2 else 200):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 200:
        if b.turn == chess.WHITE:
            n += 1
            if not check(b.fen()):
                fails += 1
                if fails > 5: sys.exit(1)
        moves = list(b.legal_moves)
        # bias towards captures / pawn moves / castling for variety
        b.push(random.choice(moves))
print("positions", n, "fails", fails, "time/pos", (time.time() - t0) / max(n, 1))
